-- 📚 꼭집 주거 사전 — 공고 간 중복 지원 제한 — 세 규칙 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.3초 · 결과:
-- {"anns": 168, "r1": 127, "r2": 138, "r3": 34, "r3_std": {"매입임대": 34}, "ex1": ["21390_부산광역시_사하구", "20648_1_경기도_광명시", "20647_1_경기도_광명시"], "ex2": ["SH_310653", "SH_310650", "21390_부산광역시_사하구"], "ex3": ["2015122300020873", "2015122300020843", "2015122300020842"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),d as(select announcement_id,std,bool_or(t~'예비입주자' and t~'중복')r1,bool_or(t~'(1인|1세대|한 세대|세대당)[^.]{0,30}(1개|1곳|한 곳|하나|1주택|1호)|중복\s*신청[^.]{0,20}(불가|무효|부적격|제한)')r2,bool_or(t~'(다른|타)\s*[^.]{0,15}공고[^.]{0,40}(신청|중복)[^.]{0,10}(불가|제한)|여러\s*(개의\s*)?(입주자\s*)?모집\s*공고')r3 from y where cls='중복선정·중복신청' group by 1,2)select json_build_object('anns',(select count(*) from d),'r1',(select count(distinct announcement_id) from d where r1),'r2',(select count(distinct announcement_id) from d where r2),'r3',(select count(distinct announcement_id) from d where r3),'r3_std',(select json_object_agg(std,n) from(select std,count(*)n from d where r3 group by 1)q),'ex1',(select json_agg(i) from(select distinct announcement_id i from d where r1 order by 1 desc limit 3)q),'ex2',(select json_agg(i) from(select distinct announcement_id i from d where r2 order by 1 desc limit 3)q),'ex3',(select json_agg(i) from(select distinct announcement_id i from d where r3 order by 1 desc limit 3)q))j;
